import { ExperimentDefinition, ExperimentInstance, ExperimentMetrics, RenderSurface, seededRandom, clearSurface, text, clamp } from './types';

export type RLMode = 'q-learning' | 'sarsa';
export type Action = 0 | 1 | 2 | 3;
const moves: Array<[number, number]> = [[1, 0], [0, 1], [-1, 0], [0, -1]];

export class TabularRLExperiment implements ExperimentInstance {
  get definition(): ExperimentDefinition { return this.mode === 'q-learning' ? qLearningDefinition : sarsaDefinition; }
  cols = 10; rows = 7; start = [0, 0] as [number, number]; goal = [9, 6] as [number, number]; agent = [0, 0] as [number, number]; q: number[][]; obstacles = new Set<string>(); alpha = .28; gamma = .92; epsilon = .22; mode: RLMode; episode = 0; episodeSteps = 0; totalReward = 0; successes = 0; private random: () => number;
  constructor(mode: RLMode, seed = 42) { this.mode = mode; this.random = seededRandom(seed); this.q = []; this.makeMap(); this.reset(); }
  init(): void { this.reset(); }
  private makeMap(): void { this.obstacles.clear(); for (let y = 1; y < this.rows - 1; y += 1) { if (y !== 3) this.obstacles.add(`4,${y}`); } for (let x = 5; x < 9; x += 1) if (x !== 7) this.obstacles.add(`${x},4`); }
  private stateIndex(x: number, y: number): number { return y * this.cols + x; }
  private valid(x: number, y: number): boolean { return x >= 0 && y >= 0 && x < this.cols && y < this.rows && !this.obstacles.has(`${x},${y}`); }
  reset(): void { const states = this.cols * this.rows; this.q = Array.from({ length: states }, () => [0, 0, 0, 0]); this.agent = [...this.start] as [number, number]; this.episode = 0; this.episodeSteps = 0; this.totalReward = 0; this.successes = 0; }
  setSeed(seed: number): void { this.random = seededRandom(seed); this.reset(); }
  setParameter(name: string, value: number | string | boolean): void { if (name === 'alpha' && typeof value === 'number') this.alpha = clamp(value, .01, 1); if (name === 'gamma' && typeof value === 'number') this.gamma = clamp(value, 0, 1); if (name === 'epsilon' && typeof value === 'number') this.epsilon = clamp(value, 0, 1); }
  private choose(state: number): Action { if (this.random() < this.epsilon) return Math.floor(this.random() * 4) as Action; const row = this.q[state]; const max = Math.max(...row); const ties = row.map((v, i) => v === max ? i : -1).filter(i => i >= 0); return ties[Math.floor(this.random() * ties.length)] as Action; }
  private transition(action: Action): { state: number; reward: number; done: boolean } { const [dx, dy] = moves[action]; const nx = this.agent[0] + dx; const ny = this.agent[1] + dy; if (!this.valid(nx, ny)) return { state: this.stateIndex(this.agent[0], this.agent[1]), reward: -.18, done: false }; this.agent = [nx, ny]; if (nx === this.goal[0] && ny === this.goal[1]) return { state: this.stateIndex(nx, ny), reward: 1, done: true }; return { state: this.stateIndex(nx, ny), reward: -.012, done: false }; }
  step(): void {
    const state = this.stateIndex(this.agent[0], this.agent[1]); const action = this.choose(state); const { state: next, reward, done } = this.transition(action); const nextAction = this.choose(next); const bootstrap = this.mode === 'q-learning' ? Math.max(...this.q[next]) : this.q[next][nextAction]; const target = reward + (done ? 0 : this.gamma * bootstrap); this.q[state][action] += this.alpha * (target - this.q[state][action]); this.episodeSteps += 1; this.totalReward += reward;
    if (done || this.episodeSteps > 100) { if (done) this.successes += 1; this.episode += 1; this.agent = [...this.start] as [number, number]; this.episodeSteps = 0; }
  }
  getMetrics(): ExperimentMetrics { const state = this.stateIndex(this.agent[0], this.agent[1]); return { mode: this.mode, episode: this.episode, successRate: this.episode ? this.successes / this.episode : 0, agentState: state, qMax: Math.max(...this.q[state]), alpha: this.alpha, gamma: this.gamma, epsilon: this.epsilon }; }
  render({ ctx, width, height }: RenderSurface): void {
    clearSurface({ ctx, width, height }, '#080b10'); text(ctx, this.mode === 'q-learning' ? 'Q-LEARNING · OFF-POLICY' : 'SARSA · ON-POLICY', 28, 22, 13, '#e0e6ee'); const cell = Math.min((width * .62 - 56) / this.cols, (height - 84) / this.rows); const ox = 28; const oy = 48;
    for (let y = 0; y < this.rows; y += 1) for (let x = 0; x < this.cols; x += 1) { const s = this.stateIndex(x, y); const qMax = Math.max(...this.q[s]); const shade = clamp((qMax + .3) / 1.2, 0, 1); ctx.fillStyle = this.obstacles.has(`${x},${y}`) ? '#303842' : `rgba(79,125,144,${.16 + shade * .46})`; ctx.fillRect(ox + x * cell, oy + y * cell, cell - 1, cell - 1); if (!this.obstacles.has(`${x},${y}`) && !(x === this.goal[0] && y === this.goal[1])) { const a = this.q[s].indexOf(qMax); const arrows = ['→', '↓', '←', '↑']; text(ctx, arrows[a], ox + (x + .5) * cell, oy + (y + .5) * cell, Math.max(10, cell * .42), '#c7d5db'); } }
    ctx.fillStyle = '#d8bd68'; ctx.fillRect(ox + this.goal[0] * cell + cell * .22, oy + this.goal[1] * cell + cell * .22, cell * .56, cell * .56); ctx.fillStyle = '#e5e9ee'; ctx.beginPath(); ctx.arc(ox + (this.agent[0] + .5) * cell, oy + (this.agent[1] + .5) * cell, Math.max(4, cell * .2), 0, Math.PI * 2); ctx.fill();
    const px = width * .68; text(ctx, 'TABULAR UPDATE', px, 74, 11, '#91a1af'); text(ctx, 'Q(s,a) ← Q(s,a) + α[ r + γV(s′) − Q(s,a) ]', px, 102, 11, '#d7e0e8'); text(ctx, `episode ${this.episode}`, px, 148, 13, '#b9c3ce'); text(ctx, `success ${(this.getMetrics().successRate as number * 100).toFixed(0)}%`, px, 174, 13, '#8fc6a1'); text(ctx, `α ${this.alpha.toFixed(2)}   γ ${this.gamma.toFixed(2)}`, px, 200, 12, '#d6ad62'); text(ctx, `ε ${this.epsilon.toFixed(2)}`, px, 224, 12, '#9aaab7'); text(ctx, 'Arrows are learned greedy actions.', px, 268, 11, '#8996a3');
  }
}

export const qLearningDefinition: ExperimentDefinition = { id: 'q-learning', name: 'Q-Learning', year: 1989, category: 'reinforcement', description: 'An off-policy temporal-difference learner discovers a route through a grid world.', historicalNote: 'Q-learning was introduced by Chris Watkins in 1989; this tabular reconstruction uses an explicit ε-greedy policy.', historicalContext: 'Watkins’ Q-learning made it possible to learn an optimal action-value function while following an exploratory policy.', coreIdea: 'Use the best next action value, even if exploration selected another action.', significance: 'A foundational off-policy reinforcement-learning algorithm.', reference: 'C. J. C. H. Watkins, Learning from Delayed Rewards (1989)', tags: ['reinforcement', 'TD learning'], formula: 'Q(s,a) ← Q(s,a) + α[r + γ maxₐ Q(s′,a) − Q(s,a)]', defaultDuration: 16, supportsInteraction: true, create: (seed = 42) => new TabularRLExperiment('q-learning', seed) };
export const sarsaDefinition: ExperimentDefinition = { id: 'sarsa', name: 'SARSA', year: 1994, category: 'reinforcement', description: 'An on-policy temporal-difference learner compares its chosen next action.', historicalNote: 'SARSA is an on-policy TD control method; the name records the state-action-reward-state-action tuple.', historicalContext: 'SARSA updates from the next action actually selected by the current behaviour policy.', coreIdea: 'Learn the value of the policy being followed, including its exploratory choices.', significance: 'Contrasts cleanly with Q-learning’s off-policy target.', tags: ['reinforcement', 'on-policy'], formula: 'Q(s,a) ← Q(s,a) + α[r + γQ(s′,a′) − Q(s,a)]', defaultDuration: 16, supportsInteraction: true, create: (seed = 42) => new TabularRLExperiment('sarsa', seed) };
