import React from 'react';

interface Props { open: boolean; quality: 'auto' | 'low' | 'medium' | 'high' | 'ultra'; reducedMotion: boolean; highContrast: boolean; sound: boolean; captureMetadata?: boolean; onQuality: (v: Props['quality']) => void; onReducedMotion: (v: boolean) => void; onHighContrast: (v: boolean) => void; onSound: (v: boolean) => void; onCaptureMetadata?: (v: boolean) => void; onClose: () => void; }
export function SettingsPanel({ open, quality, reducedMotion, highContrast, sound, captureMetadata = false, onQuality, onReducedMotion, onHighContrast, onSound, onCaptureMetadata, onClose }: Props) {
  if (!open) return null;
  return <aside className="aem-settings-panel" aria-label="Museum settings"><div className="aem-panel-head"><h2>Settings</h2><button type="button" onClick={onClose} aria-label="Close settings">×</button></div><label>Render quality<select value={quality} onChange={e => onQuality(e.target.value as Props['quality'])}><option value="auto">Auto</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option><option value="ultra">Ultra</option></select></label><label className="aem-check"><input type="checkbox" checked={reducedMotion} onChange={e => onReducedMotion(e.target.checked)} /> Reduce motion</label><label className="aem-check"><input type="checkbox" checked={highContrast} onChange={e => onHighContrast(e.target.checked)} /> High contrast</label><label className="aem-check"><input type="checkbox" checked={sound} onChange={e => onSound(e.target.checked)} /> Soundscape (off by default)</label><label className="aem-check"><input type="checkbox" checked={captureMetadata} onChange={e => onCaptureMetadata?.(e.target.checked)} /> Include screenshot metadata</label><p>Quality changes rendering density, never the algorithm's result.</p></aside>;
}
